// ─────────────────────────────────────────────────────────────
// Prepare Message  (deterministic, no AI)
// One place that turns ANY channel into the same shape for the agent:
//   • Telegram (bot chat)
//   • Webhook: website form / Meta lead form / Google lead form / WhatsApp / CSV row / tests
// Output: channel, lead_id (= sheet row + memory key), source, text, agent_input, duplicate flag.
// ─────────────────────────────────────────────────────────────
const inJson = $input.first().json;
const toAscii = (s) => String(s ?? '').replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));

// Saudi / GCC mobile → +9665XXXXXXXX (null if not valid)
function normMobile(v) {
  let m = toAscii(v).replace(/[^\d+]/g, '');
  if (m.startsWith('00')) m = '+' + m.slice(2);
  if (/^05\d{8}$/.test(m)) m = '+966' + m.slice(1);
  else if (/^5\d{8}$/.test(m)) m = '+966' + m;
  else if (/^9665\d{8}$/.test(m)) m = '+' + m;
  return /^\+9665\d{8}$/.test(m) ? m : null;
}

// ── 1) Call slots for the booking step (KSA time, Sun–Thu, 10:00 / 13:00 / 16:00) ──
const DAYS = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
const MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
const K = 3 * 3600 * 1000;
const ksa = (t) => { const d = new Date(t + K); return { y: d.getUTCFullYear(), m: d.getUTCMonth(), d: d.getUTCDate(), dow: d.getUTCDay() }; };
const now = Date.now();
const p = ksa(now);
const slots = [];
for (let i = 0; i < 21 && slots.length < 3; i++) {
  const midnight = Date.UTC(p.y, p.m, p.d + i) - K;
  const day = ksa(midnight + 12 * 3600 * 1000);
  if (day.dow === 5 || day.dow === 6) continue; // Fri / Sat off
  for (const h of [10, 13, 16]) {
    const t = midnight + h * 3600 * 1000;
    if (t < now + 2 * 3600 * 1000) continue;
    const part = h < 12 ? 'صباحاً' : h < 15 ? 'ظهراً' : 'عصراً';
    slots.push(`${slots.length + 1}) ${DAYS[day.dow]} ${day.d} ${MONTHS[day.m]} - الساعة ${h > 12 ? h - 12 : h}:00 ${part}`);
    if (slots.length === 3) break;
  }
}
const today = ksa(now);

// ── 2) Read the channel ──
let out;
if (inJson.message && inJson.message.chat) {
  // Telegram
  const msg = inJson.message;
  // Telegram re-delivers old updates after downtime: never answer a message older than 10 minutes
  if (Math.floor(now / 1000) - (msg.date || 0) > 600) return [];
  const from = msg.from || {};
  out = {
    channel: 'telegram',
    chat_id: msg.chat.id,
    lead_id: 'FANA-TG-' + msg.chat.id,
    source: 'Telegram',
    campaign: 'FANA Al Tilal Al Sharqiya Auction',
    text: toAscii(msg.text || msg.caption || '').trim(),
    name: [from.first_name, from.last_name].filter(Boolean).join(' ').replace(/[^\p{L}\p{M}\s'-]/gu, '').trim(),
    mobile: null,
    email: null,
    event_key: 'telegram:' + msg.message_id + ':' + msg.chat.id,
  };
} else {
  // Webhook: accept the field names each source really sends
  let b = inJson.body && typeof inJson.body === 'object' ? inJson.body : inJson;
  const wa = b.entry?.[0]?.changes?.[0]?.value;                 // WhatsApp Cloud API shape
  if (wa?.messages?.[0]) {
    const m = wa.messages[0];
    b = { source: 'whatsapp', from: m.from, text: m.text?.body, profile_name: wa.contacts?.[0]?.profile?.name, message_id: m.id };
  }
  if (Array.isArray(b.user_column_data)) {                        // Google Ads lead form shape
    const g = Object.fromEntries(b.user_column_data.map((c) => [c.column_id, c.string_value]));
    b = { ...b, source: b.source || 'google_form', full_name: g.FULL_NAME, phone_number: g.PHONE_NUMBER, email: g.EMAIL, city: g.CITY };
  }
  const pick = (...keys) => { for (const k of keys) if (b[k] !== undefined && b[k] !== null && String(b[k]).trim() !== '') return String(b[k]).trim(); return null; };
  const SOURCES = { whatsapp: 'WhatsApp', meta_form: 'Meta Lead Form', google_form: 'Google Lead Form', landing_page: 'Website Form', website: 'Website Chat', csv: 'CSV Import', test: 'Test' };
  const srcKey = (pick('source') || 'website').toLowerCase();
  const rawMobile = pick('phone', 'phone_number', 'mobile', 'Mobile', 'الجوال', 'رقم الجوال', 'from', 'wa_id');
  const mobile = normMobile(rawMobile);
  const email = (pick('email', 'Email', 'البريد', 'الإيميل') || '').toLowerCase();
  const eventId = pick('event_id', 'leadgen_id', 'lead_id', 'message_id', 'row_id');
  const session = pick('session_id', 'sessionId');
  const extra = [pick('العقار', 'asset', 'interest'), pick('الميزانية', 'budget')].filter(Boolean);
  out = {
    channel: 'webhook',
    chat_id: null,
    // one lead per person: chat session first, then mobile, then email, then the event
    lead_id: 'FANA-' + (session ? 'S-' + session : mobile ? 'M-' + mobile : email ? 'E-' + email : rawMobile ? 'R-' + toAscii(rawMobile).replace(/\D/g, '') : 'X-' + (eventId || now)),
    source: SOURCES[srcKey] || srcKey,
    campaign: pick('campaign', 'campaign_name', 'campaign_id') || 'FANA Al Tilal Al Sharqiya Auction',
    text: toAscii([pick('message', 'text', 'chatInput', 'الرسالة', 'ملاحظات'), ...extra].filter(Boolean).join(' - ')),
    name: pick('name', 'full_name', 'profile_name', 'الاسم', 'Name'),
    mobile,
    mobile_raw: rawMobile,
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null,
    event_key: eventId ? srcKey + ':' + eventId : null,
  };
}

// ── 3) Replayed event? (same source + event id already processed) ──
// Workflow static data persists between production executions of the active workflow.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const duplicate = !!(out.event_key && store.seen.includes(out.event_key));
if (out.event_key && !duplicate) { store.seen.push(out.event_key); if (store.seen.length > 1000) store.seen.shift(); }

// ── 4) What the agent sees (customer message + internal context it must not show) ──
const known = [
  `القناة: ${out.source}`,
  `اسم العميل: ${out.name || 'غير معروف'}`,
  out.mobile ? `جوال العميل (من النموذج/القناة، لا تسأل عنه): ${out.mobile}` : out.mobile_raw ? `جوال مكتوب في النموذج وغير صحيح: ${out.mobile_raw}` : null,
  out.email ? `إيميل العميل: ${out.email}` : null,
].filter(Boolean).join('\n');

return [{
  json: {
    ...out,
    duplicate,
    slots: slots.map((x) => x.replace(/^\d\)\s*/, '')),
    agent_input:
      `رسالة العميل: ${out.text || '(رسالة فارغة - رحّب به واسأله عن العقار اللي يهمه)'}\n\n` +
      `[سياق داخلي - لا تعرضه كما هو]\n${known}\n` +
      `تاريخ اليوم (السعودية): ${DAYS[today.dow]} ${today.d} ${MONTHS[today.m]} ${today.y}\n` +
      `المواعيد المتاحة لمكالمة مستشار المبيعات (استخدمها كما هي فقط):\n${slots.join('\n')}`,
  },
}];

// calculate_lead_score (Code Tool): deterministic, explainable scoring.
// The LLM only EXTRACTS facts; score, priority, status, labels are computed HERE,
// so identical facts always give the identical result.
const q = typeof query === 'string' ? JSON.parse(query) : (query || {});
const CATALOG = {
  'TS-01': ['أرض تجارية - المريكبات (476 م²)', 'land', 1150000], 'TS-02': ['أرض تجارية - المريكبات (448 م²)', 'land', 1050000],
  'TS-03': ['فيلا سكنية - الفيحاء', 'villa', 1100000], 'TS-04': ['فيلا سكنية - النخيل', 'villa', 930000],
  'TS-05': ['فيلا سكنية - العقربية', 'villa', 1300000], 'TS-06': ['عمارة سكنية - الجلوية', 'residential_building', 1850000],
  'TS-07': ['عمارة سكنية - طيبة', 'residential_building', 2220000], 'TS-08': ['عمارة تجارية - التحلية', 'commercial_building', 3100000],
  'TS-09': ['عمارة تجارية - النزهة', 'commercial_building', 5100000], 'TS-10': ['شقة سكنية - النور', 'apartment', 304000],
  'TS-11': ['فيلا سكنية - طيبة', 'villa', 1250000],
};
const TYPE_LABEL = { villa: 'Villa', apartment: 'Apartment', land: 'Land', residential_building: 'Residential Building', commercial_building: 'Commercial Building' };
const W = {
  budget: { Strong: 20, Partial: 10, Unknown: 5, Poor: 0 },
  asset: { Strong: 15, Partial: 8, Unknown: 4, Poor: 0 },
  fin: { 'Cash ready': 20, 'Pre-approved financing': 15, 'Financing needed': 8, Unknown: 4, 'Not ready': 0 },
  tl: { Immediately: 15, 'Within 1 month': 12, '1–3 months': 8, '3–6 months': 4, '6+ months': 0, Unknown: 3 },
  intent: { 'Ready to participate': 30, Serious: 20, Browsing: 5, 'No intent': 0, Unknown: 5 },
};
const pick = (v, obj) => (v in obj ? v : 'Unknown');
const fin = pick(q.financial_readiness, W.fin);
const tl = pick(String(q.timeline || '').replace('-', '–'), W.tl);
let intent = pick(q.intent_strength, W.intent);
const uncertain = Array.isArray(q.uncertain_fields) ? q.uncertain_fields.filter((f) => f && f !== 'Unknown') : [];

// mobile: KSA / GCC only, otherwise invalid (agent asks again)
let m = String(q.mobile || '').replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[^\d+]/g, '');
if (m.startsWith('00')) m = '+' + m.slice(2);
if (/^05\d{8}$/.test(m)) m = '+966' + m.slice(1);
else if (/^5\d{8}$/.test(m)) m = '+966' + m;
else if (/^9665\d{8}$/.test(m)) m = '+' + m;
const mobileValid = /^\+9665\d{8}$/.test(m) || /^\+(971|965|973|974|968)\d{8,9}$/.test(m);

// asset fit: only real catalog assets count
const id = CATALOG[q.interested_asset_id] ? q.interested_asset_id : null;
const type = id ? CATALOG[id][1] : (TYPE_LABEL[q.property_type] ? q.property_type : null);
const typeIds = Object.keys(CATALOG).filter((k) => CATALOG[k][1] === type);
let assetFit = 'Unknown';
if (id) assetFit = 'Strong';
else if (typeIds.length) assetFit = 'Partial';
else if (q.property_type && q.property_type !== 'Unknown') assetFit = 'Poor'; // something the auction doesn't have

// budget fit vs opening prices
const bmin = Number(q.budget_min_sar) || 0;
const bmax = Number(q.budget_max_sar) || 0;
const ref = bmax || bmin;
const budgetKnown = !!ref && !uncertain.includes('budget');
const pool = (id ? [id] : typeIds.length ? typeIds : Object.keys(CATALOG)).map((k) => CATALOG[k][2]);
const cheapest = Math.min(...Object.values(CATALOG).map((a) => a[2]));
let budgetFit = 'Unknown';
if (budgetKnown) {
  if (pool.some((x) => ref >= x)) budgetFit = 'Strong';
  else if (pool.some((x) => ref >= x * 0.9)) budgetFit = 'Partial';
  else budgetFit = 'Poor';
}

// contradiction guard: gave budget + payment + timeline → not "just browsing"
if (intent === 'Browsing' && budgetKnown && fin !== 'Unknown' && tl !== 'Unknown') intent = 'Serious';

const breakdown = { budget_fit: W.budget[budgetFit], asset_fit: W.asset[assetFit], financial_readiness: W.fin[fin], timeline: W.tl[tl], intent_strength: W.intent[intent] };
const score = Object.values(breakdown).reduce((a, b) => a + b, 0);

// priority gates (first match wins). Missing info NEVER disqualifies.
const ORDER = ['P1', 'P2', 'P3', 'Disqualified'];
let priority; let status;
if (q.do_not_contact) { priority = 'Disqualified'; status = 'Disqualified'; }
else if (intent === 'No intent') { priority = 'Disqualified'; status = 'Disqualified'; }
else if (budgetKnown && ref < cheapest * 0.9) { priority = 'Disqualified'; status = 'Disqualified'; }
else if (score >= 80 && ['Cash ready', 'Pre-approved financing'].includes(fin) && ['Strong', 'Partial'].includes(assetFit)
         && ['Strong', 'Partial'].includes(budgetFit) && ['Immediately', 'Within 1 month'].includes(tl) && !uncertain.length) { priority = 'P1'; status = 'Qualified'; }
else if (uncertain.length) { priority = 'P2'; status = 'Needs clarification'; }
else if (score >= 60) { priority = 'P2'; status = 'Follow-up'; }
else { priority = 'P3'; status = 'Nurture'; }
// a person who asks for a human is never below P2 (unless they asked not to be contacted)
if (q.human_requested && priority !== 'Disqualified') {
  status = 'Human requested';
  if (ORDER.indexOf(priority) > 1) priority = 'P2';
}

// labels the agent must copy into the sheet as-is
const fmt = (n) => Number(n).toLocaleString('en-US');
const assetLabel = id ? `${CATALOG[id][0]} (${id})` : 'Unknown';
const typeLabel = type ? TYPE_LABEL[type] : 'Unknown';
const budgetLabel = !ref ? 'Unknown' : bmin && bmax && bmin !== bmax ? `SAR ${fmt(bmin)} – ${fmt(bmax)}` : `SAR ${fmt(ref)}`;
const readiness = q.do_not_contact ? 'Do not contact' : q.contact_later ? 'Contact later' : intent;

// factual Arabic reason (what sales reads first)
const FIN_AR = { 'Cash ready': 'كاش جاهز', 'Pre-approved financing': 'موافقة تمويل مبدئية', 'Financing needed': 'يحتاج تمويل', 'Not ready': 'غير جاهز مالياً', Unknown: 'الدفع غير معروف' };
const TL_AR = { Immediately: 'يدخل هذا المزاد', 'Within 1 month': 'خلال شهر', '1–3 months': 'خلال 1-3 أشهر', '3–6 months': 'خلال 3-6 أشهر', '6+ months': 'بعد 6 أشهر', Unknown: 'التوقيت غير معروف' };
const parts = [];
if (q.do_not_contact) parts.push('طلب عدم التواصل');
if (q.human_requested) parts.push('طلب التحدث مع موظف');
if (uncertain.length) parts.push(`غير مؤكد: ${uncertain.join('، ')}`);
const TYPE_AR = { villa: 'فيلا', apartment: 'شقة', land: 'أرض تجارية', residential_building: 'عمارة سكنية', commercial_building: 'عمارة تجارية' };
parts.push(id ? CATALOG[id][0] : type ? `مهتم بـ${TYPE_AR[type]} (بدون عقار محدد)` : 'العقار غير محدد');
if (ref) parts.push(`ميزانية ${fmt(ref)} ريال (${budgetFit === 'Strong' ? 'تغطي' : budgetFit === 'Partial' ? 'قريبة' : budgetFit === 'Poor' ? 'أقل من السعر' : 'غير مؤكدة'})`);
if (priority === 'Disqualified' && budgetKnown && ref < cheapest * 0.9) parts.push(`أقل من أرخص سعر افتتاحي ${fmt(cheapest)}`);
parts.push(FIN_AR[fin]);
parts.push(TL_AR[tl]);
if (intent === 'Browsing') parts.push('يستفسر عن الأسعار فقط');
if (q.contact_later) parts.push('طلب التواصل لاحقاً');
// high score but not P1 → say exactly what blocks it
if (priority === 'P2' && score >= 70) {
  const block = [];
  if (!['Cash ready', 'Pre-approved financing'].includes(fin)) block.push('التمويل غير محسوم بعد');
  if (!['Strong', 'Partial'].includes(budgetFit)) block.push('الميزانية لا تغطي السعر الافتتاحي');
  if (!['Immediately', 'Within 1 month'].includes(tl)) block.push('التوقيت ليس قريباً');
  if (block.length) parts.push('⚠ ليس P1 لأن: ' + block.join('، '));
}

const missing = [['mobile', mobileValid], ['asset', assetFit !== 'Unknown'], ['budget', budgetKnown],
  ['financial_readiness', fin !== 'Unknown'], ['timeline', tl !== 'Unknown']].filter(([, ok]) => !ok).map(([k]) => k);
const bookable = (priority === 'P1' || priority === 'P2') && status !== 'Needs clarification' && mobileValid;

return JSON.stringify({
  mobile_normalized: mobileValid ? m : null,
  mobile_valid: mobileValid,
  duplicate_key: mobileValid ? m : 'Unknown',
  interested_asset_label: assetLabel,
  property_type_label: typeLabel,
  budget_range_label: budgetLabel,
  intent_strength: intent,
  purchase_readiness: readiness,
  budget_fit: budgetFit,
  asset_fit: assetFit,
  lead_score: score,
  score_breakdown: breakdown,
  priority,
  qualification_status: status,
  score_reason: parts.join('؛ '),
  missing_fields: missing,
  booking_allowed: bookable,
  next_step: !mobileValid ? 'اطلب رقم جوال سعودي صحيح (مثل 05xxxxxxxx) قبل الحفظ'
    : priority === 'Disqualified' ? 'اعرض الملخص، احفظ بعد التأكيد، واشكر العميل بلطف بدون عرض حجز'
    : status === 'Human requested' ? 'اعرض الملخص، احفظ بعد التأكيد، ثم أكد أن موظف سيتواصل واعرض المواعيد'
    : bookable ? 'اعرض الملخص، احفظ بعد التأكيد، ثم اعرض المواعيد الثلاثة للحجز'
    : 'اعرض الملخص، احفظ بعد التأكيد، ثم أخبره أن الفريق سيرسل له التفاصيل',
});

// ─────────────────────────────────────────────────────────────
// Check Save / Booking  (deterministic guard after the agent)
// 1) CLEAN: n8n memory stores tool calls as text «[Used tools: …]»; the model sometimes
//    copies that into its reply. The customer must never see it → strip it.
// 2) RECOVER: if the model WROTE «Tool: Save_FANA_Lead, Input: {…}» instead of really
//    calling the tool, parse that input and save it for real (next nodes).
// 3) BOOKING: if the reply confirms a slot («تم حجز/تغيير») but nothing was saved,
//    write the Appointment ourselves.
// Any of the three → run the sheet + HubSpot sync.
// ─────────────────────────────────────────────────────────────
const pm = $('Prepare Message').first().json;
const raw = String($json.output || '');
const saved = JSON.stringify($json.intermediateSteps || []).includes('Save_FANA_Lead');

// read one JSON object starting at position i (balanced braces, strings respected)
function readJson(s, i) {
  let depth = 0, inStr = false, esc = false;
  for (let k = i; k < s.length; k++) {
    const c = s[k];
    if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
    if (c === '"') inStr = true;
    else if (c === '{' || c === '[') depth++;
    else if (c === '}' || c === ']') { depth--; if (depth === 0) return { text: s.slice(i, k + 1), end: k + 1 }; }
  }
  return null;
}

// 2) recover a save that was only written as text
let recovered = null;
const mark = raw.indexOf('Tool: Save_FANA_Lead, Input:');
if (!saved && mark !== -1) {
  const start = raw.indexOf('{', mark);
  const obj = start !== -1 ? readJson(raw, start) : null;
  try { recovered = obj ? JSON.parse(obj.text) : null; } catch (e) { recovered = null; }
}

// 1) strip every «Used tools: … Result: […]» block
let reply = raw;
for (let guard = 0; guard < 5 && reply.includes('Used tools'); guard++) {
  const i = reply.indexOf('Used tools');
  const from = reply[i - 1] === '[' ? i - 1 : i;
  const r = reply.indexOf('Result:', i);
  let end = -1;
  if (r !== -1) {
    const b = reply.indexOf('[', r);
    const block = b !== -1 ? readJson(reply, b) : null;
    end = block ? block.end : -1;
  }
  if (end === -1) { reply = reply.slice(0, from); break; }
  if (reply[from] === '[' && reply[end] === ']') end++;
  reply = (reply.slice(0, from) + reply.slice(end)).trim();
}
reply = reply.replace(/^[\],\s]+/, '').trim() || 'تم ✅ شكراً لك، وبيتواصل معك فريقنا قريب إن شاء الله.';

// 3) booking confirmed in words but not saved
const norm = (t) => String(t).replace(/[\s\-–:٫,،]/g, '').replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
let appointment = null;
if (/تم\s*(حجز|تغيير|تعديل|تأكيد)/.test(reply) || /موعدك/.test(reply)) {
  const r = norm(reply);
  appointment = (pm.slots || []).find((slot) => r.includes(norm(slot))) || null;
}
if (!appointment && recovered && recovered.appointment && recovered.appointment !== 'Not booked') appointment = recovered.appointment;

// a broken email must never reach HubSpot
if (recovered && recovered.email && !/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(recovered.email)) recovered.email = 'Unknown';

return [{ json: { lead_id: pm.lead_id, reply, saved, recovered, appointment, sync: saved || !!recovered || !!appointment } }];

// ─────────────────────────────────────────────────────────────
// HubSpot · Prepare  (runs only on turns where the agent SAVED the lead)
// Reads the saved sheet row (the source of truth) and builds:
//   • the contact search (by stored ID / phone in 2 formats / email) → no duplicates
//   • contact properties + deal properties (all case-study fields mapped)
// ─────────────────────────────────────────────────────────────
const row = $input.first().json || {};
const U = (v) => (v === undefined || v === null || String(v).trim() === '' || String(v).trim() === 'Unknown' ? null : String(v).trim());

// the sheet may hold the phone as a number (966523456789) or 05… → always +9665XXXXXXXX
function normMobile(v) {
  let m = String(v ?? '').replace(/[^\d+]/g, '');
  if (m.startsWith('00')) m = '+' + m.slice(2);
  if (/^05\d{8}$/.test(m)) m = '+966' + m.slice(1);
  else if (/^5\d{8}$/.test(m)) m = '+966' + m;
  else if (/^9665\d{8}$/.test(m)) m = '+' + m;
  return /^\+\d{11,13}$/.test(m) ? m : null;
}
const mobile = normMobile(U(row['Mobile']));
const emailRaw = U(row['Email']);
const email = emailRaw && /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(emailRaw) ? emailRaw.toLowerCase() : null;  // «name@gmail» → not sent
const leadId = U(row['Lead ID']) || $('Prepare Message').first().json.lead_id;
const doNotContact = /do not contact/i.test(row['Consent / Contact Status'] || '');

// no row, no way to reach the person, or asked not to be contacted → don't push to the CRM
if (!row['Lead ID'] || (!mobile && !email) || doNotContact) {
  const keep = (v) => (v && /^\d+$/.test(String(v)) ? String(v) : null);
  return [{ json: { skip: true, lead_id: leadId, created_date: U(row['Created Date']),
    stored_contact_id: keep(row['HubSpot Contact ID']), stored_deal_id: keep(row['HubSpot Deal ID']), reason: !row['Lead ID'] ? 'row not found' : doNotContact ? 'do not contact' : 'no mobile/email' } }];
}

// contact search: any ONE matching filter group is enough
const groups = [];
if (mobile) {
  const local = mobile.startsWith('+966') ? '0' + mobile.slice(4) : mobile;
  const variants = [...new Set([mobile, local, mobile.replace('+', '')])];
  groups.push({ filters: [{ propertyName: 'phone', operator: 'IN', values: variants }] });
  groups.push({ filters: [{ propertyName: 'mobilephone', operator: 'IN', values: variants }] });
}
if (email) groups.push({ filters: [{ propertyName: 'email', operator: 'EQ', value: email }] });

const parts = String(U(row['Name']) || '').split(/\s+/).filter(Boolean);
const contact = { firstname: parts[0], lastname: parts.slice(1).join(' ') || undefined, phone: mobile || undefined, mobilephone: mobile || undefined, email: email || undefined, city: U(row['City']) || undefined };
Object.keys(contact).forEach((k) => contact[k] === undefined && delete contact[k]);

// budget → amount (largest number in "SAR 800,000 – 900,000")
const nums = String(row['Budget Range'] || '').replace(/,/g, '').match(/\d+(\.\d+)?/g) || [];
const amount = nums.length ? Math.max(...nums.map(Number)) : null;
const asset = U(row['Interested Asset']) || U(row['Property Type']) || 'غير محدد';
const priority = U(row['Priority']) || 'P3';

const description = [
  `الأولوية: ${priority} (${row['Score'] ?? '-'}/100) — ${row['Qualification Status'] || '-'}`,
  `السبب: ${row['Score Reason'] || '-'}`,
  `العقار: ${asset} | النوع: ${row['Property Type'] || '-'}`,
  `الميزانية: ${row['Budget Range'] || '-'} (${row['Budget Fit'] || '-'})`,
  `الدفع: ${row['Financial Readiness'] || '-'} | التوقيت: ${row['Timeline'] || '-'} | النية: ${row['Intent Strength'] || '-'}`,
  `الغرض: ${row['Investment Purpose'] || '-'} | نوع المشتري: ${row['Buyer Type'] || '-'} | خبرة مزادات: ${row['Auction Experience'] || '-'}`,
  `التواصل المفضل: ${row['Preferred Contact Method'] || '-'} | الموعد: ${row['Appointment'] || 'Not booked'}`,
  `المصدر: ${row['Source'] || '-'} / ${row['Campaign'] || '-'} | Lead ID: ${leadId}`,
  `ملخص: ${row['AI Summary'] || '-'}`,
].join('\n');

const deal = {
  dealname: `مزاد التلال الشرقية - ${U(row['Name']) || mobile || email} - ${asset}`,
  hs_priority: priority === 'P1' ? 'high' : priority === 'P2' ? 'medium' : 'low',
  description,
  // custom deal properties created by "▶ Setup HubSpot (run once)"
  fana_priority: priority,
  fana_score: Number(row['Score']) || 0,
  fana_reason: String(row['Score Reason'] || '').slice(0, 1000),
  fana_status: U(row['Qualification Status']) || 'Unknown',
  fana_asset: asset,
  fana_timeline: U(row['Timeline']) || 'Unknown',
  fana_funding: U(row['Financial Readiness']) || 'Unknown',
  fana_source: U(row['Source']) || 'Unknown',
  fana_ai_summary: String(row['AI Summary'] || '').slice(0, 1000),
};
if (amount) deal.amount = amount;

return [{
  json: {
    skip: false,
    lead_id: leadId,
    created_date: U(row['Created Date']),
    stored_contact_id: U(row['HubSpot Contact ID']) && /^\d+$/.test(row['HubSpot Contact ID']) ? String(row['HubSpot Contact ID']) : null,
    stored_deal_id: U(row['HubSpot Deal ID']) && /^\d+$/.test(row['HubSpot Deal ID']) ? String(row['HubSpot Deal ID']) : null,
    disqualified: priority === 'Disqualified',
    search_body: { filterGroups: groups, properties: ['firstname', 'phone', 'email'], limit: 5 },
    contact,
    deal,
  },
}];

// ─────────────────────────────────────────────────────────────
// HubSpot · Contact request
// Stored ID (from an earlier save) → PATCH it.
// Found by phone/email (already in HubSpot, e.g. scenario 8) → PATCH that one.
// Nothing found → create a new contact.
// ─────────────────────────────────────────────────────────────
const prep = $('HS Prepare').first().json;
const search = $input.first().json || {};
const found = Array.isArray(search.results) ? search.results : [];
const existingId = prep.stored_contact_id || found[0]?.id || null;

return [{
  json: {
    action: prep.stored_contact_id ? 'updated' : found.length ? 'updated_existing' : 'created',
    method: existingId ? 'PATCH' : 'POST',
    url: existingId ? `https://api.hubapi.com/crm/v3/objects/contacts/${existingId}` : 'https://api.hubapi.com/crm/v3/objects/contacts',
    body: { properties: prep.contact },
    possible_duplicates: found.length > 1 ? found.map((f) => f.id) : [],
    search_error: search.error ? String(search.error.message || search.error).slice(0, 150) : null,
  },
}];

// ─────────────────────────────────────────────────────────────
// HubSpot · Deal request
// One deal per customer for this auction:
//   stored deal ID → PATCH · existing FANA deal on this contact → PATCH · else create + associate.
// Stage is set ONLY when the deal is created, so a stage moved by sales is never reset.
// ─────────────────────────────────────────────────────────────
const prep = $('HS Prepare').first().json;
const saved = $('HS Save Contact').first().json || {};
const contactId = saved.id || null;
const dealSearch = $input.first().json || {};
const existingDeal = prep.stored_deal_id || dealSearch.results?.[0]?.id || null;

if (!contactId) {
  return [{ json: { skip_deal: true, contact_id: null, contact_error: String(saved.error?.description || saved.error?.message || saved.message || 'contact not saved').slice(0, 200) } }];
}

const properties = { ...prep.deal };
if (existingDeal) {
  return [{ json: { skip_deal: false, contact_id: contactId, method: 'PATCH', url: `https://api.hubapi.com/crm/v3/objects/deals/${existingDeal}`, body: { properties } } }];
}
properties.pipeline = 'default';
properties.dealstage = prep.disqualified ? 'closedlost' : 'appointmentscheduled';
return [{
  json: {
    skip_deal: false,
    contact_id: contactId,
    method: 'POST',
    url: 'https://api.hubapi.com/crm/v3/objects/deals',
    body: {
      properties,
      // deal → contact, HubSpot-defined association type 3
      associations: [{ to: { id: contactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 3 }] }],
    },
  },
}];

// ─────────────────────────────────────────────────────────────
// Write back to the sheet: HubSpot IDs (or the error, so nothing fails silently)
// and Created Date only the first time.
// Reached from 3 places: deal saved · deal skipped (contact failed) · lead not pushed (no mobile / do-not-contact).
// ─────────────────────────────────────────────────────────────
const prep = $('HS Prepare').first().json;
const now = $now.setZone('Asia/Riyadh').toFormat('yyyy-MM-dd HH:mm');
if (prep.reason === 'row not found') return [];

const created = prep.created_date || now;
if (prep.skip) {
  // say clearly why this lead was not sent (instead of leaving an old error in the cells)
  const why = prep.reason === 'no mobile/email' ? 'لم يُرسل: لا يوجد جوال صحيح ولا إيميل صحيح' : prep.reason === 'do not contact' ? 'لم يُرسل: العميل طلب عدم التواصل' : 'لم يُرسل: ' + prep.reason;
  return [{ json: { 'Lead ID': prep.lead_id, 'Created Date': created,
    'HubSpot Contact ID': prep.stored_contact_id || why, 'HubSpot Deal ID': prep.stored_deal_id || why } }];
}

const req = $('HS Deal Request').first().json;
const dealRan = $('HS Save Deal').isExecuted;
const deal = dealRan ? $('HS Save Deal').first().json : {};
const dealId = !req.skip_deal && deal.id ? String(deal.id) : null;
const dealErr = req.skip_deal ? 'skipped: contact not saved' : dealId ? null : String(deal.error?.description || deal.error?.message || deal.message || 'deal not saved').slice(0, 150);

return [{
  json: {
    'Lead ID': prep.lead_id,
    // keep a good stored ID; the error goes next to it in the Deal column so it is still visible
    'HubSpot Contact ID': req.contact_id ? String(req.contact_id) : prep.stored_contact_id || `ERROR: ${req.contact_error}`,
    'HubSpot Deal ID': dealId || prep.stored_deal_id || `ERROR: ${req.skip_deal ? 'contact: ' + req.contact_error : dealErr}`,
    'Created Date': created,
  },
}];

// ─────────────────────────────────────────────────────────────
// ▶ Setup HubSpot (run once): creates the 9 custom Deal properties (free plan allows 10)
// and one "existing" test contact for scenario 8. Safe to re-run (409 = already exists).
// ─────────────────────────────────────────────────────────────
const P = (name, label, type = 'string', fieldType = 'text') => ({ kind: 'property', body: { name, label, type, fieldType, groupName: 'dealinformation' } });
return [
  P('fana_priority', 'FANA Priority'),
  P('fana_score', 'FANA Score', 'number', 'number'),
  P('fana_reason', 'FANA Priority Reason', 'string', 'textarea'),
  P('fana_status', 'FANA Qualification Status'),
