]);

// ✓ created · ✓ already exists (409) · ✗ error → fix the token scopes and run again
const asked = $('Setup Items').all().map((i) => i.json);
return $input.all().map((it, i) => {
  const r = it.json || {};
  const msg = String(r.error?.description || r.error?.message || r.message || '');
